"use client"

import { Suspense, useEffect, useState } from "react"
import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation"
import { Message, MessageContent } from "@/components/ai-elements/message"
import { AssistantTurn } from "@/components/cockpit/assistant-turn"
import { CallDetailDialog } from "@/components/cockpit/call-detail-dialog"
import { CandidatePanel } from "@/components/cockpit/candidate-panel"
import { CockpitShell } from "@/components/cockpit/cockpit-shell"
import {
  DecisionBar,
  type DecisionStatus,
} from "@/components/cockpit/decision-bar"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { IncidentHeader } from "@/components/cockpit/incident-header"
import { IncidentRequestMessage } from "@/components/cockpit/incident-request-message"
import { MessageComposer } from "@/components/cockpit/message-composer"
import { SCRIPT, TICK_MS } from "@/lib/case-001"

export function CockpitChat() {
  const [visible, setVisible] = useState(0)
  const [approved, setApproved] = useState(false)
  const [candidatesOpen, setCandidatesOpen] = useState(true)
  const [draft, setDraft] = useState("")
  const [messages, setMessages] = useState<string[]>([])
  const running = visible < SCRIPT.length

  useEffect(() => {
    if (!running) return

    const id = window.setInterval(() => {
      setVisible((count) => Math.min(count + 1, SCRIPT.length))
    }, TICK_MS)
    return () => window.clearInterval(id)
  }, [running])

  const latestStep = SCRIPT[Math.min(visible, SCRIPT.length) - 1]
  const currentStep =
    visible === 0
      ? "Launching"
      : latestStep.kind === "decision"
        ? "Decision ready"
        : latestStep.stepName
  const checksPassed = isStepVisible("tests", visible)
  const decisionExists = isStepVisible("strategy", visible)
  const decisionStatus: DecisionStatus = approved
    ? "approved"
    : !running && !checksPassed
      ? "on hold"
      : checksPassed
        ? "needs human review"
        : "evaluating"

  function replay() {
    const skipTicks = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    setVisible(skipTicks ? SCRIPT.length : 0)
    setApproved(false)
  }

  function sendMessage(message: string) {
    const text = message.trim()
    if (!text) return

    setMessages((current) => [...current, text])
    setDraft("")
  }

  return (
    <CockpitShell
      rightSidebar={
        candidatesOpen ? (
          <CandidatePanel
            visible={visible}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden">
        <IncidentHeader
          visible={visible}
          approved={approved}
          running={running}
          onReplay={replay}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-[50vw] gap-4 px-4 py-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <IncidentRequestMessage />
            {SCRIPT.slice(0, visible).map((step, index) => (
              <AssistantTurn
                key={step.id}
                step={step}
                latest={index === visible - 1 && running}
              />
            ))}
            {running ? (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <DotLoader className="size-4" />
                <span>{currentStep}</span>
              </div>
            ) : null}
            {messages.map((message, index) => (
              <Message key={`${index}-${message}`} from="user">
                <MessageContent>
                  <p>{message}</p>
                </MessageContent>
              </Message>
            ))}
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
        <div className="shrink-0 bg-background">
          {decisionExists ? (
            <DecisionBar
              checksPassed={checksPassed}
              status={decisionStatus}
              onApprove={() => setApproved(true)}
            />
          ) : null}
          <MessageComposer
            value={draft}
            onChange={setDraft}
            onSend={sendMessage}
          />
        </div>
      </div>
      <Suspense fallback={null}>
        <CallDetailDialog />
      </Suspense>
    </CockpitShell>
  )
}

function isStepVisible(stepId: string, visible: number): boolean {
  const index = SCRIPT.findIndex((step) => step.id === stepId)
  return index >= 0 && visible > index
}
import {
  Message,
  MessageContent,
  MessageResponse,
} from "@/components/ai-elements/message"
import {
  Task,
  TaskContent,
  TaskItem,
  TaskTrigger,
} from "@/components/ai-elements/task"
import {
  Tool,
  ToolContent,
  ToolHeader,
  ToolOutput,
} from "@/components/ai-elements/tool"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { CANDIDATES, type ScriptStep } from "@/lib/case-001"

export function AssistantTurn({
  step,
  latest,
}: {
  step: ScriptStep
  latest: boolean
}) {
  return (
    <Message from="assistant" className="max-w-full">
      <MessageContent className="w-full max-w-full">
        <MessageResponse>
          {step.kind === "decision"
            ? "Decision ready for human review."
            : step.summary}
        </MessageResponse>
        {step.method && step.path ? (
          <Tool defaultOpen={false} className="mb-0">
            <ToolHeader
              type={`tool-${step.id}`}
              state={latest ? "input-available" : "output-available"}
              title={`${step.method} ${step.path}`}
            />
            <ToolContent>
              <ToolOutput
                output={<p className="p-3 text-pretty">{step.detail}</p>}
                errorText={undefined}
              />
            </ToolContent>
          </Tool>
        ) : null}
        <StepExtras step={step} />
      </MessageContent>
    </Message>
  )
}

function StepExtras({ step }: { step: ScriptStep }) {
  if (step.kind === "outreach") return <OutreachTasks />

  if (step.kind === "policy") {
    return (
      <Alert variant="destructive">
        <AlertTitle>Shenzhen Bearing Co rejected</AlertTitle>
        <AlertDescription>
          Rule <span className="font-mono">blocked_origin_country</span>. No
          Outreach Task.
        </AlertDescription>
      </Alert>
    )
  }

  if (step.kind === "deltas") {
    return (
      <p className="text-sm text-muted-foreground">
        Munich Motion Claim is{" "}
        <Badge variant="destructive">in_stock_allocated</Badge> — that stock is
        not ours.
      </p>
    )
  }

  if (step.kind === "decision") {
    return (
      <p className="text-sm text-muted-foreground">
        Winning Strategy: split 20% SKF air + 80% FAG sea. Required checks
        passed.
      </p>
    )
  }

  return null
}

function OutreachTasks() {
  const candidates = CANDIDATES.filter(
    (candidate) => candidate.compliance === "passed"
  )

  return (
    <Task defaultOpen>
      <TaskTrigger title="Outreach Tasks · 4 parallel" />
      <TaskContent className="[&>div]:mt-2 [&>div]:grid [&>div]:gap-2 [&>div]:border-l-0 [&>div]:pl-0 sm:[&>div]:grid-cols-2">
        {candidates.map((candidate) => (
          <TaskItem
            key={candidate.name}
            className="flex min-w-0 items-center justify-between gap-2 rounded-md border border-border px-2.5 py-2"
          >
            <span className="min-w-0">
              <span className="block truncate text-foreground">
                {candidate.name}
              </span>
              <span className="font-mono text-xs">{candidate.phone}</span>
            </span>
            <Badge variant="secondary">calling</Badge>
          </TaskItem>
        ))}
      </TaskContent>
    </Task>
  )
}
"use client"

import { ChevronDownIcon, XIcon } from "@/components/icons"
import { CandidateComparison } from "@/components/cockpit/candidate-comparison"
import { RejectedCandidate } from "@/components/cockpit/rejected-candidate"
import {
  claimStatus,
  complianceStatus,
  landedCostStatus,
  outreachStatus,
  stockStatus,
} from "@/components/cockpit/candidate-status"
import type {
  Candidate,
  CandidateState,
} from "@/components/cockpit/candidate-types"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { CALLS, CANDIDATES, LANDED_LINES, SCRIPT } from "@/lib/case-001"
import { cn } from "@/lib/utils"

export function CandidatePanel({
  visible,
  onClose,
}: {
  visible: number
  onClose: () => void
}) {
  const visibleIds = new Set(SCRIPT.slice(0, visible).map((step) => step.id))
  const state: CandidateState = {
    candidatesVisible: visibleIds.has("suppliers"),
    policyComplete: visibleIds.has("policy"),
    outreachStarted: visibleIds.has("outreach"),
    claimsComplete: visibleIds.has("claims"),
    costsComplete: visibleIds.has("deltas"),
  }
  const candidates = state.candidatesVisible ? CANDIDATES : []

  return (
    <aside
      aria-label="Candidates"
      className="flex h-full w-full min-w-0 flex-col overflow-hidden bg-sidebar text-foreground"
    >
      <header className="flex min-h-11 shrink-0 items-center justify-between border-b border-border px-3">
          <h2 className="text-sm font-medium">Candidates</h2>
        <Button
          type="button"
          size="icon-sm"
          variant="ghost"
          aria-label="Close Candidates sidebar"
          onClick={onClose}
        >
          <XIcon aria-hidden="true" />
        </Button>
      </header>
      {candidates.length === 0 ? (
        <p className="p-4 text-sm text-muted-foreground">
          No Candidates matched yet.
        </p>
      ) : (
        <div className="min-h-0 flex-1 overflow-y-auto">
          {candidates.map((candidate) => (
            <CandidateRow
              key={candidate.name}
              candidate={candidate as Candidate}
              state={state}
              visibleIds={visibleIds}
            />
          ))}
        </div>
      )}
    </aside>
  )
}

function CandidateRow({
  candidate,
  state,
  visibleIds,
}: {
  candidate: Candidate
  state: CandidateState
  visibleIds: ReadonlySet<string>
}) {
  const rejected = state.policyComplete && candidate.compliance === "failed"
  const call = CALLS.find(
    (item) => item.candidateId === candidate.id && visibleIds.has(item.afterId)
  )
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )

  return (
    <Collapsible className="border-b border-border">
      <CollapsibleTrigger className="group flex min-h-10 w-full items-center gap-2 px-3 py-2 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset">
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-2">
            <span className="truncate text-sm font-medium">
              {candidate.name}
            </span>
            <span className="shrink-0 font-mono text-xs text-muted-foreground">
              {candidate.country}
            </span>
          </span>
          <CandidateStatuses candidate={candidate} state={state} />
        </span>
        <LifecycleBadge candidate={candidate} state={state} />
        <ChevronDownIcon
          aria-hidden
          className="size-4 shrink-0 text-muted-foreground transition-transform group-data-[panel-open]:rotate-180 motion-reduce:transition-none"
        />
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div className="border-t border-border bg-background/50 px-3 py-3">
          {rejected ? (
            <RejectedCandidate candidate={candidate} />
          ) : (
            <CandidateComparison
              candidate={candidate}
              state={state}
              call={call}
              landedLine={landedLine}
            />
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

function CandidateStatuses({
  candidate,
  state,
}: {
  candidate: Candidate
  state: CandidateState
}) {
  const allocated =
    state.claimsComplete && candidate.stockStatus === "in_stock_allocated"
  const values = [
    [
      "compliance",
      complianceStatus(candidate, state),
      state.policyComplete && candidate.compliance === "failed",
    ],
    ["Outreach Task", outreachStatus(candidate, state), false],
    ["Claim", claimStatus(candidate, state), false],
    ["stock_status", stockStatus(candidate, state), allocated],
    ["Landed Cost", landedCostStatus(candidate, state), false],
  ] as const

  return (
    <span className="mt-1 flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
      {values.map(([label, value, destructive]) => (
        <span
          key={label}
          className={cn("whitespace-nowrap", destructive && "text-destructive")}
        >
          {label} <span className="font-mono text-foreground">{value}</span>
        </span>
      ))}
    </span>
  )
}

function LifecycleBadge({
  candidate,
  state,
}: {
  candidate: Candidate
  state: CandidateState
}) {
  if (state.policyComplete && candidate.compliance === "failed")
    return <Badge variant="destructive">rejected</Badge>
  if (state.claimsComplete)
    return <Badge variant="secondary">Claim filed</Badge>
  if (state.outreachStarted) return <Badge variant="outline">outreach</Badge>
  if (state.policyComplete) return <Badge variant="secondary">passed</Badge>
  return <Badge variant="outline">matched</Badge>
}
import { CheckIcon, ChevronDownIcon } from "@/components/icons"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { STRATEGIES } from "@/lib/case-001"

export type DecisionStatus =
  "evaluating" | "on hold" | "needs human review" | "approved"

type DecisionBarProps = {
  checksPassed: boolean
  status: DecisionStatus
  onApprove: () => void
}

export function DecisionBar({
  checksPassed,
  status,
  onApprove,
}: DecisionBarProps) {
  const approved = status === "approved"
  const recommended = STRATEGIES.find((strategy) => strategy.recommended)!

  return (
    <div className="mx-auto w-full max-w-[50vw] px-4 pt-3">
      <Collapsible>
        <Card size="sm" className="w-full gap-0 py-0 ring-0 bg-accent">
          <CollapsibleContent className="border-b border-border/70 px-3 py-3">
            <DecisionDetails checksPassed={checksPassed} />
          </CollapsibleContent>
          <div className="flex min-w-0 items-center gap-3 px-3 py-2">
            <CollapsibleTrigger
              className="group flex min-w-0 flex-1 items-center gap-3 text-left"
              aria-label="Toggle Decision details"
            >
              <ChevronDownIcon className="size-4 shrink-0 text-muted-foreground transition-transform duration-200 ease-[cubic-bezier(0.77,0,0.175,1)] group-data-[panel-open]:-rotate-90 motion-reduce:transition-none" />
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">Decision</span>
                  <DecisionStatusBadge status={status} />
                </div>
                <p className="truncate text-xs text-muted-foreground">
                  {recommended.name}
                </p>
              </div>
              <span className="shrink-0 text-sm font-medium tabular-nums">
                {recommended.total}
              </span>
            </CollapsibleTrigger>
            <Button
              type="button"
              size="sm"
              variant={approved ? "secondary" : "default"}
              disabled={!checksPassed || approved}
              onClick={onApprove}
            >
              {approved ? <CheckIcon data-icon="inline-start" /> : null}
              {approved ? "Approved" : "Mark approved"}
            </Button>
          </div>
        </Card>
      </Collapsible>
    </div>
  )
}

function DecisionDetails({ checksPassed }: { checksPassed: boolean }) {
  return (
    <div className="grid gap-4 text-sm sm:grid-cols-2">
      <div className="flex flex-col gap-2">
        <p className="font-medium">Rationale</p>
        <p className="text-muted-foreground">
          SKF air protects the line-stop. FAG sea lowers total Landed Cost for
          the remaining quantity.
        </p>
        <p className="font-medium">Runner-ups</p>
        {STRATEGIES.filter((strategy) => !strategy.recommended).map(
          (strategy) => (
            <div
              key={strategy.name}
              className="flex justify-between gap-3 text-xs text-muted-foreground"
            >
              <span>{strategy.name}</span>
              <span className="shrink-0 tabular-nums">{strategy.total}</span>
            </div>
          )
        )}
      </div>
      <div className="flex flex-col gap-2">
        <p className="font-medium">Required checks</p>
        {(["Policy", "Cost model"] as const).map((check) => (
          <div
            key={check}
            className="flex items-center justify-between gap-3 rounded-md border border-border px-2.5 py-2"
          >
            <span>{check}</span>
            <Badge variant={checksPassed ? "secondary" : "outline"}>
              {checksPassed ? "passed" : "evaluating"}
            </Badge>
          </div>
        ))}
        <p className="text-xs text-muted-foreground">
          Approval is local rehearsal state. It does not place an order.
        </p>
      </div>
    </div>
  )
}

function DecisionStatusBadge({ status }: { status: DecisionStatus }) {
  if (status === "approved") return <Badge variant="secondary">approved</Badge>
  if (status === "on hold") return <Badge variant="destructive">on hold</Badge>
  if (status === "needs human review") return null
  return <Badge variant="outline">evaluating</Badge>
}
"use client"

import { useState, type KeyboardEvent, type PointerEvent } from "react"
import { LogoIcon } from "@/components/logo"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@/components/ui/sidebar"
import { INCIDENTS } from "@/lib/case-001"

type SessionSidebarProps = {
  width: number
  onResizeStart: (event: PointerEvent<HTMLButtonElement>) => void
  onResize: (event: PointerEvent<HTMLButtonElement>) => void
  onResizeEnd: (event: PointerEvent<HTMLButtonElement>) => void
  onResizeKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void
}

export function SessionSidebar({
  width,
  onResizeStart,
  onResize,
  onResizeEnd,
  onResizeKeyDown,
}: SessionSidebarProps) {
  const [activeSession, setActiveSession] = useState<
    (typeof INCIDENTS)[number]["caseId"]
  >(INCIDENTS[0].caseId)

  return (
    <Sidebar collapsible="offcanvas" className="h-dvh">
      <SidebarHeader className="h-11 items-start justify-center border-b border-border/70 px-4 py-0">
