          aria-label="SupplyOS"
          className="size-5 text-sidebar-foreground"
        />
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup className="flex-1 py-3">
          <SidebarGroupLabel>Sessions</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {INCIDENTS.map((incident) => (
                <SidebarMenuItem key={incident.caseId}>
                  <SidebarMenuButton
                    size="lg"
                    isActive={incident.caseId === activeSession}
                    onClick={() => setActiveSession(incident.caseId)}
                  >
                    <span className="min-w-0">
                      <span className="block font-mono text-xs">
                        {incident.caseId}
                      </span>
                      <span className="block truncate text-xs text-sidebar-foreground/60">
                        {incident.partLabel}
                      </span>
                    </span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail
        resizable
        aria-valuemin={10}
        aria-valuemax={20}
        aria-valuenow={Math.round(width)}
        onPointerDown={onResizeStart}
        onPointerMove={onResize}
        onPointerUp={onResizeEnd}
        onPointerCancel={onResizeEnd}
        onKeyDown={onResizeKeyDown}
      />
    </Sidebar>
  )
}
import {
  ChevronDownIcon,
  CostIcon,
  FactoryIcon,
  type IconComponent,
  LineStopIcon,
  PanelRightOpenIcon,
  PartIcon,
  QuantityIcon,
  RotateCcwIcon,
  WarehouseIcon,
} from "@/components/icons"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { RunStatusButton } from "@/components/cockpit/run-status-button"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { SidebarTrigger } from "@/components/ui/sidebar"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { INCIDENT } from "@/lib/case-001"

const hoursToLineStop = Number(INCIDENT.lineStopDays) * 24
const standingStill = `${INCIDENT.lineStopCostPerHour.replace(/\.00$/, "")} / h`

type IncidentHeaderProps = {
  visible: number
  approved: boolean
  running: boolean
  onReplay: () => void
  showOpenCandidates: boolean
  onOpenCandidates: () => void
}

export function IncidentHeader(props: IncidentHeaderProps) {
  return (
    <Collapsible className="shrink-0">
      <header className="group/incident-header flex h-11 items-center gap-2 border-b border-border/70 bg-background px-3">
        <SidebarTrigger className="md:hidden" />
        <CollapsibleTrigger
          className="group/incident-trigger flex min-w-0 flex-1 items-center gap-4 rounded-md px-1 py-1 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
