          />
        </CollapsibleTrigger>
        <HeaderActions {...props} />
      </header>
      <CollapsibleContent className="border-b border-border/70 bg-muted/20">
        <dl className="grid gap-x-6 gap-y-4 px-4 py-4 sm:grid-cols-2 xl:grid-cols-3">
          <IncidentProperty
            icon={FactoryIcon}
