            value={`${INCIDENT.partId} · ${INCIDENT.description}`}
          />
          <IncidentProperty
            icon={QuantityIcon}
            label="Quantity short"
            value={formatQuantity(INCIDENT.shortfall)}
          />
          <IncidentProperty
