  const [selected, setSelected] = useState<Candidate | null>(null)
  const visibleIds = new Set(SCRIPT.slice(0, visible).map((step) => step.id))
  const state: CandidateState = {
    candidatesVisible: visibleIds.has("suppliers"),
    policyComplete: visibleIds.has("policy"),
    outreachStarted: visibleIds.has("outreach"),
    claimsComplete: visibleIds.has("claims"),
    costsComplete: visibleIds.has("deltas"),
  }

  if (!state.candidatesVisible) return null

  function scrollRail(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return

    event.preventDefault()
    event.stopPropagation()
    railRef.current?.scrollBy({
      left: event.key === "ArrowRight" ? 260 : -260,
      behavior: "smooth",
    })
  }

  return (
    <section aria-labelledby="inline-candidates-title" className="min-w-0">
      <div className="mb-2 flex items-end justify-between gap-3">
        <div>
          <h2 id="inline-candidates-title" className="text-sm font-medium">
            Candidates
          </h2>
          <p className="text-xs text-muted-foreground">
            Select a Candidate to inspect its Supplier Record and Claims.
          </p>
        </div>
        <span className="shrink-0 text-xs text-muted-foreground">
          {CANDIDATES.length} matched
        </span>
      </div>
      <div
        ref={railRef}
        role="region"
        aria-label="Candidate cards"
        tabIndex={0}
        onKeyDown={scrollRail}
        className="chat-scrollbar flex snap-x gap-3 overflow-x-auto px-px pb-2 outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {CANDIDATES.map((candidate) => {
          const candidateValue = candidate as Candidate
          const status = getLifecycleStatus(candidateValue, state)

          return (
            <button
              key={candidate.id}
              type="button"
              aria-label={`Open ${candidate.name} Candidate details`}
              aria-pressed={selected?.id === candidate.id}
              onClick={() => setSelected(candidateValue)}
              className="w-56 shrink-0 snap-start rounded-xl text-left outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <Card
                size="sm"
                className={cn(
                  "h-full transition-colors hover:bg-muted/50",
                  selected?.id === candidate.id && "bg-muted/50"
                )}
              >
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <FactoryIcon
                      aria-hidden="true"
                      className="size-3.5 text-muted-foreground"
                    />
                    <span className="truncate">{candidate.name}</span>
                  </CardTitle>
                  <CardDescription className="truncate text-xs">
                    {candidate.country} ·{" "}
                    {candidate.supplierRecord.preferred
                      ? "Preferred Supplier Record"
                      : "Supplier Record"}
                  </CardDescription>
                  <CardAction>
                    <span
                      className={cn(
                        "inline-flex h-4.5 items-center gap-1 rounded-full px-1.5 text-[10px] font-medium text-foreground",
                        status.className
                      )}
                    >
                      <span
                        aria-hidden="true"
                        className={cn(
                          "size-2 rounded-full",
                          status.dotClassName
                        )}
                      />
                      {status.label}
                    </span>
                  </CardAction>
                </CardHeader>
                <CardContent className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
                  <span>{candidate.recordUnit} record unit</span>
                  <ArrowRightIcon aria-hidden="true" className="size-3.5" />
                </CardContent>
              </Card>
            </button>
          )
        })}
      </div>

      <CandidateDetailsSheetPrototype
        candidate={selected}
        state={state}
        visibleIds={visibleIds}
        onOpenChange={(open) => {
          if (!open) setSelected(null)
        }}
      />
    </section>
  )
}

function CandidateDetailsSheetPrototype({
  candidate,
  state,
  visibleIds,
  onOpenChange,
}: {
  candidate: Candidate | null
  state: CandidateState
  visibleIds: ReadonlySet<string>
  onOpenChange: (open: boolean) => void
}) {
  if (!candidate) return null

  const rejected = state.policyComplete && candidate.compliance === "failed"
  const call = CALLS.find(
    (item) => item.candidateId === candidate.id && visibleIds.has(item.afterId)
  )
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )

  return (
    <Sheet
      open
      modal={false}
      disablePointerDismissal
      onOpenChange={onOpenChange}
    >
      <SheetContent
        side="right"
        overlayClassName="pointer-events-none"
        className="w-[min(28rem,calc(100vw-2rem))] sm:max-w-md"
      >
        <SheetHeader className="border-b border-border pr-12">
          <SheetTitle>{candidate.name}</SheetTitle>
          <SheetDescription>
            {candidate.country} ·{" "}
            {candidate.supplierRecord.preferred
              ? "Preferred Supplier Record"
              : "Supplier Record"}
          </SheetDescription>
        </SheetHeader>
        <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-4">
          {rejected ? (
            <RejectedCandidate candidate={candidate} />
          ) : (
            <CandidateComparison
              candidate={candidate}
              state={state}
              call={call}
              landedLine={landedLine}
            />
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

function getLifecycleStatus(candidate: Candidate, state: CandidateState) {
  if (state.policyComplete && candidate.compliance === "failed") {
    return {
      label: "rejected",
      className: "bg-destructive/30",
      dotClassName: "bg-destructive",
    }
  }
  if (state.claimsComplete) {
    return {
      label: "Claim filed",
      className: "bg-chart-5/30",
      dotClassName: "bg-chart-5",
    }
  }
  if (state.outreachStarted) {
    return {
      label: "outreach",
      className: "bg-chart-1/30",
      dotClassName: "bg-chart-1",
    }
  }
  if (state.policyComplete) {
    return {
      label: "passed",
      className: "bg-primary/30",
      dotClassName: "bg-primary",
    }
  }
  return {
    label: "matched",
    className: "bg-muted-foreground/30",
    dotClassName: "bg-muted-foreground",
  }
}
