// PROTOTYPE: Development-only switcher for the two /chat Candidate layouts.
import { useEffect } from "react"

import { ChevronLeftIcon, ChevronRightIcon } from "@/components/icons"
import { Button } from "@/components/ui/button"

export type CockpitPrototypeVariant = "default" | "inline-candidates"

export function PrototypeVariantSwitcher({
  variant,
  onChange,
}: {
  variant: CockpitPrototypeVariant
  onChange: (variant: CockpitPrototypeVariant) => void
}) {
  useEffect(() => {
    function cycle(event: globalThis.KeyboardEvent) {
      const target = event.target as HTMLElement | null
      if (
        target?.matches("input, textarea, [contenteditable], [contenteditable='true']")
      ) {
        return
      }
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return

      onChange(variant === "default" ? "inline-candidates" : "default")
    }

    window.addEventListener("keydown", cycle)
    return () => window.removeEventListener("keydown", cycle)
  }, [onChange, variant])

  if (process.env.NODE_ENV === "production") return null

  const next = variant === "default" ? "inline-candidates" : "default"
  const label =
    variant === "default" ? "Default sidebar" : "Inline Candidate cards"

  return (
    <div className="fixed bottom-3 left-1/2 z-40 flex -translate-x-1/2 items-center gap-1 rounded-full bg-foreground p-1 text-background shadow-lg">
      <Button
        type="button"
        size="icon-sm"
        variant="ghost"
        className="text-background hover:bg-background/15 hover:text-background"
        aria-label="Previous prototype variant"
        onClick={() => onChange(next)}
      >
        <ChevronLeftIcon aria-hidden="true" />
      </Button>
      <span className="min-w-40 px-2 text-center text-xs font-medium">
        {label}
      </span>
      <Button
        type="button"
        size="icon-sm"
        variant="ghost"
        className="text-background hover:bg-background/15 hover:text-background"
        aria-label="Next prototype variant"
        onClick={() => onChange(next)}
      >
        <ChevronRightIcon aria-hidden="true" />
      </Button>
    </div>
  )
}
